add_claim("THE STADIUM IS MODULAR: FTG classifies stadium components in internally animal-codenamed asset folders, each an independent file of modular construction pieces - sides, corners and ends plus environmental textures - which is how the game assembles the stand puzzle when facilities are upgraded.", 3, "stadium/modular-asset-architecture", [e_skill], notes="An asset review, not gameplay - explains why the sector ladder behaves as it does")
add_claim("STADIUM BUILD ORDER: 'Don't build the roofs, just until you reach max spectators', and upgrade ONE stand at a time - 'if your whole stadium lvl is 13 then don't upgrade every stand 16 or 17 upgrade one stand to 27' - which is cheaper than levelling every stand together.", 3, "stadium/build-order-roofs-and-one-stand", [e_skill])
add_claim("DOCUMENTED NEGATIVES: DLS26 has NO controller support on mobile, and there is NO gem-based injury healing - 'No gem healing - either wait it out or use medical staff'.", 2, "negatives/no-controller-no-gem-healing", [e_skill])
add_claim("playdreamleaguesoccer.com is REJECTED for the FOURTH time: it publishes 'Version 9.4.0 - May 2, 2026' for a game at v13.420, claims training raises OVR 'from 60 to 99' against the confirmed 86 ceiling, and invents skill moves (elastico, rabona, trivela) that no other source lists. Its 'each stadium level costs 100 gems' claim is likewise rejected against the coin-based ladder.", 1, "sources/playdreamleaguesoccer-rejected-fourth-time", [e_skill], notes="Fourth independent confirmation of AI-farm status")

for name in ('EV-480_skill_moves_controls_stadium.html',):
    p=os.path.join(RAW_DIR,name)
    if not os.path.exists(p):
        with open(p,'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
